import random
import itertools
import json
from problems import ThreeSat, ThreeColoring
from reduce import reduce


def brute_sat(instance):
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for bits in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            lit_true = False
            for lit in clause:
                var = abs(lit) - 1
                val = bits[var]
                if lit > 0:
                    lit_true = lit_true or val
                else:
                    lit_true = lit_true or (not val)
                if lit_true:
                    break
            if not lit_true:
                ok = False
                break
        if ok:
            return True
    return False


def brute_coloring(instance):
    n = instance["n"]
    edges = [(u, v) for u, v in instance["edges"]]
    for colors in itertools.product([0, 1, 2], repeat=n):
        good = True
        for u, v in edges:
            if colors[u] == colors[v]:
                good = False
                break
        if good:
            return True
    return False


def random_sat_instance(max_vars=4, max_clauses=5):
    m = random.randint(0, max_vars)
    # ensure at least 3 vars if there are clauses
    if m > 0 and random.random() < 0.5:
        num_clauses = random.randint(1, max_clauses)
    else:
        num_clauses = 0
    clauses = []
    for _ in range(num_clauses):
        # pick 3 distinct vars from 1..m (if m<3, skip)
        if m < 3:
            break
        vars_chosen = random.sample(range(1, m + 1), 3)
        clause = []
        for v in vars_chosen:
            lit = v if random.choice([True, False]) else -v
            clause.append(lit)
        clauses.append(clause)
    return {"num_vars": m, "clauses": clauses}


def run_tests(num_tests=200):
    passed = 0
    for i in range(num_tests):
        sat_inst = random_sat_instance()
        # validate
        ThreeSat.validate(sat_inst)
        graph_inst = reduce(sat_inst)
        ThreeColoring.validate(graph_inst)
        sat_ans = brute_sat(sat_inst)
        col_ans = brute_coloring(graph_inst)
        if sat_ans == col_ans:
            passed += 1
        else:
            print("Mismatch on test", i)
            print("SAT instance", sat_inst)
            print("Graph", graph_inst)
            print("SAT ans", sat_ans, "Color ans", col_ans)
            break
    return passed, num_tests

if __name__ == "__main__":
    passed, total = run_tests()
    result = {"verified": passed == total, "tests_run": total, "tests_passed": passed}
    print(json.dumps(result))
    with open("verdict.json", "w") as f:
        json.dump(result, f)
EOF"}

